1	import { INestApplication } from '@nestjs/common';
2	import { NestFactory } from '@nestjs/core';
3	import {
4	  FastifyAdapter,
5	  NestFastifyApplication,
6	} from '@nestjs/platform-fastify';
7	import * as http from 'http';
8	import * as net from 'net';
9	import WebSocket from 'ws';
10	import { AppModule } from '../src/app.module.js';
11	import { resetWsCounters, wsCounters } from '../src/graceful-ws.gateway.js';
12	
13	interface RawResponse {
14	  status: number;
15	  headers: http.IncomingHttpHeaders;
16	  body: string;
17	}
18	
19	const getJson = (port: number, path: string): Promise<RawResponse> =>
20	  new Promise<RawResponse>((resolve, reject) => {
21	    http
22	      .get(
23	        `http://localhost:${port}${path}`,
24	        { headers: { Connection: 'close' } },
25	        res => {
26	          let body = '';
27	          res.on('data', chunk => (body += chunk));
28	          res.on('end', () =>
29	            resolve({
30	              status: res.statusCode || 0,
31	              headers: res.headers,
32	              body,
33	            }),
34	          );
35	        },
36	      )
37	      .on('error', reject);
38	  });
39	
40	const openWs = (port: number) =>
41	  new Promise<WebSocket>((resolve, reject) => {
42	    const ws = new WebSocket(`ws://localhost:${port}/graceful-ws`);
43	    ws.once('open', () => resolve(ws));
44	    ws.once('error', reject);
45	  });
46	
47	const nextMessage = (ws: WebSocket) =>
48	  new Promise<string>((resolve, reject) => {
49	    ws.once('message', data => resolve(data.toString()));
50	    ws.once('error', reject);
51	  });
52	
53	const nextClose = (ws: WebSocket) =>
54	  new Promise<{ code: number; reason: string }>(resolve => {
55	    ws.once('close', (code, reason) =>
56	      resolve({ code, reason: reason.toString() }),
57	    );
58	  });
59	
60	const echo = (ws: WebSocket, data: string, delay: number) =>
61	  ws.send(JSON.stringify({ type: 'echo', data, delay }));
62	
63	const flush = (ms = 20) => new Promise<void>(r => setTimeout(r, ms));
64	
65	/** Raw HTTP/1.1 client socket with buffered response collection. */
66	const rawSocket = async (port: number) => {
67	  const socket = net.createConnection(port, '127.0.0.1');
68	  socket.on('error', () => {});
69	  await new Promise<void>(resolve => socket.once('connect', resolve));
70	  return socket;
71	};
72	
73	const readUntilEnd = (socket: net.Socket) =>
74	  new Promise<string>(resolve => {
75	    let data = '';
76	    socket.on('data', chunk => (data += chunk.toString()));
77	    socket.on('end', () => resolve(data));
78	    socket.on('close', () => resolve(data));
79	  });
80	
81	const UPGRADE_HEADERS = (port: number) =>
82	  [
83	    `GET /graceful-ws HTTP/1.1`,
84	    `Host: localhost:${port}`,
85	    `Upgrade: websocket`,
86	    `Connection: Upgrade`,
87	    `Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==`,
88	    `Sec-WebSocket-Version: 13`,
89	    '',
90	    '',
91	  ].join('\r\n');
92	
93	describe('Graceful Shutdown (Fastify WebSocket)', () => {
94	  let app: INestApplication;
95	  const clients: Array<WebSocket | net.Socket> = [];
96	
97	  const createApp = async (options: { gate?: boolean } = {}) => {
98	    const { gate = true } = options;
99	    app = await NestFactory.create<NestFastifyApplication>(
100	      AppModule,
101	      new FastifyAdapter(),
102	      {
103	        return503OnClosing: gate,
104	        logger: false,
105	      },
106	    );
107	    await app.listen(0);
108	    return app.getHttpServer().address().port as number;
109	  };
110	
111	  const trackWs = async (port: number) => {
112	    const ws = await openWs(port);
113	    clients.push(ws);
114	    return ws;
115	  };
116	
117	  const trackSocket = async (port: number) => {
118	    const socket = await rawSocket(port);
119	    clients.push(socket);
120	    return socket;
121	  };
122	
123	  beforeEach(() => {
124	    resetWsCounters();
125	  });
126	
127	  afterEach(async () => {
128	    for (const client of clients.splice(0)) {
129	      if (client instanceof WebSocket) {
130	        client.terminate();
131	      } else {
132	        client.destroy();
133	      }
134	    }
135	    if (app) {
136	      await app.close().catch(() => {});
137	    }
138	  });
139	
140	  describe('message lifecycle', () => {
141	    it('echoes data after the delay and counts completed messages', async () => {
142	      const port = await createApp();
143	      const ws = await trackWs(port);
144	
145	      const stats0 = await getJson(port, '/graceful-ws/stats');
146	      expect(JSON.parse(stats0.body)).toEqual({
147	        activeConnections: 1,
148	        completedMessages: 0,
149	        cleanupCount: 0,
150	      });
151	
152	      const started = Date.now();
153	      echo(ws, 'hello', 150);
154	      expect(await nextMessage(ws)).toBe('hello');
155	      expect(Date.now() - started).toBeGreaterThanOrEqual(100);
156	
157	      const stats1 = await getJson(port, '/graceful-ws/stats');
158	      expect(JSON.parse(stats1.body)).toEqual({
159	        activeConnections: 1,
160	        completedMessages: 1,
161	        cleanupCount: 0,
162	      });
163	    });
164	
165	    it('does not count an echo when the client aborts before it is sent', async () => {
166	      const port = await createApp();
167	      const ws = await trackWs(port);
168	
169	      echo(ws, 'late', 400);
170	      await flush(30);
171	      ws.terminate();
172	      await flush(500);
173	
174	      const stats = await getJson(port, '/graceful-ws/stats');
175	      expect(JSON.parse(stats.body)).toEqual({
176	        activeConnections: 0,
177	        completedMessages: 0,
178	        cleanupCount: 0,
179	      });
180	    });
181	
182	    it('closes only the faulting connection with 1011 "gateway error"', async () => {
183	      const port = await createApp();
184	      const faulting = await trackWs(port);
185	      const healthy = await trackWs(port);
186	
187	      faulting.send(JSON.stringify({ type: 'error' }));
188	      const closed = await nextClose(faulting);
189	      expect(closed.code).toBe(1011);
190	      expect(closed.reason).toBe('gateway error');
191	
192	      // The other connection keeps serving, and errors never count.
193	      echo(healthy, 'still here', 10);
194	      expect(await nextMessage(healthy)).toBe('still here');
195	
196	      const stats = await getJson(port, '/graceful-ws/stats');
197	      expect(JSON.parse(stats.body)).toEqual({
198	        activeConnections: 1,
199	        completedMessages: 1,
200	        cleanupCount: 0,
201	      });
202	    });
203	
204	    it('reports stats reads without mutating any counter', async () => {
205	      const port = await createApp();
206	      const ws = await trackWs(port);
207	      echo(ws, 'one', 5);
208	      expect(await nextMessage(ws)).toBe('one');
209	
210	      const first = JSON.parse(
211	        (await getJson(port, '/graceful-ws/stats')).body,
212	      );
213	      const second = JSON.parse(
214	        (await getJson(port, '/graceful-ws/stats')).body,
215	      );
216	      expect(second).toEqual(first);
217	      expect(second.completedMessages).toBe(1);
218	    });
219	  });
220	
221	  describe('drain on shutdown', () => {
222	    it('waits for a delayed echo on an established connection', async () => {
223	      const port = await createApp();
224	      const ws = await trackWs(port);
225	      echo(ws, 'drain me', 300);
226	      const reply = nextMessage(ws);
227	
228	      await flush(50);
229	      const closePromise = app.close();
230	      await flush(50);
231	
232	      // The connection is retained while its in-flight work converges.
233	      expect(ws.readyState).toBe(WebSocket.OPEN);
234	      expect(await reply).toBe('drain me');
235	
236	      await closePromise;
237	      expect(wsCounters).toEqual({
238	        activeConnections: 0,
239	        completedMessages: 1,
240	        cleanupCount: 1,
241	      });
242	    });
243	
244	    it('lets an in-flight error frame converge with code 1011', async () => {
245	      const port = await createApp();
246	      const ws = await trackWs(port);
247	
248	      ws.send(JSON.stringify({ type: 'error' }));
249	      const closedPromise = nextClose(ws);
250	
251	      // Let the error message enter in-flight processing before the shutdown
252	      // boundary is established.
253	      await flush(20);
254	      const closePromise = app.close();
255	      const closed = await closedPromise;
256	      expect(closed.code).toBe(1011);
257	      expect(closed.reason).toBe('gateway error');
258	
259	      await closePromise;
260	      expect(wsCounters).toEqual({
261	        activeConnections: 0,
262	        completedMessages: 0,
263	        cleanupCount: 1,
264	      });
265	    });
266	
267	    it('converges when a client aborts during shutdown', async () => {
268	      const port = await createApp();
269	      const ws = await trackWs(port);
270	      echo(ws, 'never sent', 500);
271	      await flush(30);
272	
273	      const closePromise = app.close();
274	      ws.terminate();
275	
276	      await closePromise;
277	      expect(wsCounters).toEqual({
278	        activeConnections: 0,
279	        completedMessages: 0,
280	        cleanupCount: 1,
281	      });
282	    });
283	
284	    it('runs cleanup exactly once across concurrent close() calls', async () => {
285	      const port = await createApp();
286	      const ws = await trackWs(port);
287	      echo(ws, 'once', 250);
288	      const reply = nextMessage(ws);
289	
290	      await flush(30);
291	      const start = Date.now();
292	      const closePromise = Promise.all([app.close(), app.close(), app.close()]);
293	      expect(Date.now() - start).toBeLessThan(200);
294	
295	      expect(await reply).toBe('once');
296	      await closePromise;
297	
298	      expect(wsCounters).toEqual({
299	        activeConnections: 0,
300	        completedMessages: 1,
301	        cleanupCount: 1,
302	      });
303	    });
304	  });
305	
306	  describe('upgrade gate after shutdown started', () => {
307	    it('rejects a new upgrade with HTTP 503, plain text and Connection: close', async () => {
308	      const port = await createApp();
309	      // An established connection keeps the server alive while closing.
310	      const established = await trackWs(port);
311	      echo(established, 'slow', 400);
312	      const reply = nextMessage(established);
313	      await flush(20);
314	
315	      const closePromise = app.close();
316	      await flush(30);
