1	import {
2	  Injectable,
3	  Logger,
4	  OnModuleDestroy,
5	  OnModuleInit,
6	} from '@nestjs/common';
7	import { HttpAdapterHost } from '@nestjs/core';
8	import type { Duplex } from 'stream';
9	import * as http from 'http';
10	import { WebSocket, type RawData, WebSocketServer } from 'ws';
11	
12	/**
13	 * Mutable counters exposed through "GET /graceful-ws/stats" while the
14	 * application is serving traffic and through the exported snapshot after the
15	 * application has closed (the listening socket is gone by then, but the
16	 * figures must remain readable without counting as new business work).
17	 */
18	export const wsCounters = {
19	  /** WebSocket connections that completed the handshake and are still open. */
20	  activeConnections: 0,
21	  /** Echo messages whose "data" was actually sent back to the client. */
22	  completedMessages: 0,
23	  /** Graceful shutdown cleanup ("onModuleDestroy") executions. */
24	  cleanupCount: 0,
25	};
26	
27	export function resetWsCounters() {
28	  wsCounters.activeConnections = 0;
29	  wsCounters.completedMessages = 0;
30	  wsCounters.cleanupCount = 0;
31	}
32	
33	interface EchoMessage {
34	  type: 'echo';
35	  data: string;
36	  delay: number;
37	}
38	
39	interface ErrorMessage {
40	  type: 'error';
41	}
42	
43	type GracefulWsMessage = EchoMessage | ErrorMessage;
44	
45	/**
46	 * Deterministic WebSocket lifecycle probe mounted at the fixed "/graceful-ws"
47	 * path of the underlying HTTP server.
48	 *
49	 * Text frames are JSON envelopes:
50	 * - { type: "echo", data: string, delay: number } waits "delay" ms and sends
51	 *   "data" back; the message counts as completed only when the reply is
52	 *   actually written, so a client aborting before the echo is sent does not
53	 *   move the counter;
54	 * - { type: "error" } closes that single connection with code 1011 and reason
55	 *   "gateway error"; other connections and the completed counter are untouched.
56	 *
57	 * The upgrade handling is "noServer": handshakes are accepted explicitly from
