/**
 * Installs a request gate in front of Fastify's routing so that, once the
 * shutdown has started, new requests are rejected with
 * "503 Service Unavailable" before they can enter the Nest pipeline
 * (middleware, guards, pipes, interceptors, handlers), while requests
 * that were already accepted run to completion.
 *
 * The gate has two layers:
 *
 * - a wrapper around the server's "request" listener, which rejects every
 *   request whose headers arrive after the shutdown started — including
 *   requests pipelined on an existing keep-alive connection. The listener
 *   is wrapped instead of using a Fastify "onRequest" hook because
 *   Fastify's own "return503OnClosing" fast path (enabled by default)
 *   runs before any hook and answers with a JSON body, which would not
 *   match the Express-compatible contract (a plain "Service Unavailable"
 *   body and a "Connection: close" header);
 * - a "preHandler" hook, which covers requests that were accepted by the
 *   first layer while the application was still running but have not
 *   reached a route handler yet when the shutdown starts — most notably
 *   requests whose body is still streaming in. Fastify runs "preHandler"
 *   hooks after the request body has been fully received and right before
 *   the route handler (where the Nest pipeline begins), so a late
 *   rejection here still happens before any guard, pipe, interceptor or
 *   controller runs and cannot trigger business side effects.
 */
private installClosingRequestGate() {
  const server = this.httpServer as unknown as http.Server;
  const routing = this.instance.routing;
  server.removeListener('request', routing);
  server.on('request', (req, res) => {
    if (!this.isShuttingDown) {
      routing(req as unknown as TRawRequest, res as unknown as TRawResponse);
      return;
    }
    if (req.httpVersionMajor !== 2) {
      res.setHeader('Connection', 'close');
    }
    res.writeHead(HttpStatus.SERVICE_UNAVAILABLE, {
      'Content-Type': 'text/plain',
    });
    res.end('Service Unavailable');
  });

  this.instance.addHook('preHandler', (request, reply, done) => {
    if (!this.isShuttingDown) {
      done();
      return;
    }
    if (request.raw.httpVersionMajor !== 2) {
      reply.header('Connection', 'close');
    }
    // Short-circuit the lifecycle without calling "done()".
    reply
      .code(HttpStatus.SERVICE_UNAVAILABLE)
      .header('Content-Type', 'text/plain')
      .send('Service Unavailable');
  });

  this.installClosingUpgradeGate();
}

/**
 * Installs an upgrade gate in front of every registered "upgrade" listener
 * (e.g. a "noServer" WebSocketServer) so that handshakes observed only after
 * the shutdown started are rejected at the HTTP layer, before the gateway
 * or any message handling can run: a plain "503 Service Unavailable"
 * response with "Connection: close", followed by socket termination.
 *
 * Upgrades observed while the application is still running - including ones
 * whose handshake bytes are still arriving when the shutdown begins - are
 * forwarded to the listeners registered at upgrade time, so already
 * accepted connections keep their existing error semantics and in-flight
 * work can drain. The server's "emit" is wrapped instead of registering an
 * "upgrade" listener so that listeners registered later (plugins attach
 * during application initialization, after the adapter) are covered as
 * well, and the gate stays the single interception point.
 */
private installClosingUpgradeGate() {
  if (this.isClosingUpgradeGateInstalled) {
    return;
  }
  this.isClosingUpgradeGateInstalled = true;

  const server = this.httpServer as unknown as http.Server;
  const originalEmit = server.emit.bind(server) as (
    event: string,
    ...args: any[]
  ) => boolean;

  server.emit = ((event: string, ...args: any[]) => {
    if (event !== 'upgrade') {
      return originalEmit(event, ...args);
    }

    const [request, socket, head] = args as [
      http.IncomingMessage,
      net.Socket,
      Buffer,
    ];
    if (!this.isShuttingDown) {
      return originalEmit('upgrade', request, socket, head);
    }

    // Reject the handshake at the HTTP layer without dispatching it to any
    // upgrade listener (gateway/message handling never runs), then close the
    // underlying connection so it cannot be reused for further requests.
    if (!socket.writable) {
      socket.destroy();
      return false;
    }
    socket.once('error', () => socket.destroy());
    socket.end(
      [
        'HTTP/1.1 503 Service Unavailable',
        'Connection: close',
        'Content-Type: text/plain',
        'Content-Length: 19',
        '',
        'Service Unavailable',
      ].join('\r\n'),
    );
    return false;
  }) as typeof server.emit;
}

private registerJsonContentParser(rawBody?: boolean) {
  const contentType = 'application/json';
  const withRawBody = !!rawBody;
  const { bodyLimit } = this.getInstance().initialConfig;

  this.useBodyParser(
    contentType,
    withRawBody,
    { bodyLimit },
    (req, body, done) => {
      const { onProtoPoisoning, onConstructorPoisoning } =
        this.instance.initialConfig;
      const defaultJsonParser = this.instance.getDefaultJsonParser(
        onProtoPoisoning || 'error',
        onConstructorPoisoning || 'error',
      ) as FastifyBodyParser<string | Buffer, TServer>;
      defaultJsonParser(req, body, done);
    },
  );
}

private registerUrlencodedContentParser(rawBody?: boolean) {
  const contentType = 'application/x-www-form-urlencoded';
  const withRawBody = !!rawBody;
  const { bodyLimit } = this.getInstance().initialConfig;

  this.useBodyParser(
    contentType,
    withRawBody,
    { bodyLimit },
    (_req, body, done) => {
      done(null, querystringParse(body.toString()));
