  // gate wrapper replacement would normally call routing when healthy
  res.writeHead(200); res.end('routed');
};
const server = http.createServer((req,res) => {
  if (shuttingDown) {
    res.setHeader('Connection','close');
    res.writeHead(503, {'Content-Type':'text/plain'});
    res.end('Service Unavailable');
  } else routing(req,res);
});

let shuttingDown = false;
const originalEmit = server.emit.bind(server);
server.emit = (event, ...args) => {
  if (event !== 'upgrade') return originalEmit(event, ...args);
  const [request, socket, head] = args;
  if (!shuttingDown) return originalEmit('upgrade', request, socket, head);
  if (!socket.writable) { socket.destroy(); return false; }
  socket.once('error', () => socket.destroy());
  socket.end(['HTTP/1.1 503 Service Unavailable','Connection: close','Content-Type: text/plain','Content-Length: 19','','Service Unavailable'].join('\r\n'));
  return false;
};

