import http from 'http';
import net from 'net';
import { WebSocketServer } from 'ws';

let shuttingDown = false;
const routing = (req,res)=>{ if(shuttingDown){res.setHeader('Connection','close');res.writeHead(503,{'Content-Type':'text/plain'});res.end('Service Unavailable');} else {res.writeHead(200);res.end('ok');} };
const server = http.createServer(routing);
const wss = new WebSocketServer({ noServer: true });
server.on('upgrade', (req,socket,head)=>{ wss.handleUpgrade(req,socket,head,ws=>wss.emit('connection',ws,req)); });

const originalEmit = server.emit.bind(server);
server.emit = (event, ...args) => {
  if (event!=='upgrade') return originalEmit(event,...args);
  const [request,socket,head]=args;
  if (!shuttingDown) return originalEmit('upgrade',request,socket,head);
  if (!socket.writable){socket.destroy();return false;}
  socket.once('error',()=>socket.destroy());
  socket.end(['HTTP/1.1 503 Service Unavailable','Connection: close','Content-Type: text/plain','Content-Length: 19','','Service Unavailable'].join('\r\n'));
  return false;
};

server.listen(0, () => {
  const port = server.address().port;
  shuttingDown = true;
  // Client receives 503 but deliberately stays OPEN (does not destroy/FIN)
  const c = net.connect(port,'127.0.0.1',()=>{ c.write('GET /graceful-ws HTTP/1.1\r\nHost: x\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n'); });
  let buf='';
  c.on('data',d=>buf+=d.toString());
  c.on('error',()=>{});
  c.resume();
  setTimeout(()=>{
    console.log('client got:', JSON.stringify(buf.slice(0,40)));
    console.log('client writable?', c.writable, 'readable?', c.readable, 'destroyed?', c.destroyed);
    console.log('server connections before close:', server.connections);
    const t=Date.now();
    server.close(()=>{
      console.log('>>> server.close() resolved after', Date.now()-t, 'ms (client still open =', !c.destroyed, ')');
      process.exit(0);
    });
    setTimeout(()=>{ console.log('!!! server.close() HUNG > 1500ms — leak'); process.exit(1); },1500);
  },300);
});
"
